-- Synthetic subset of Production's observed relational contract, 2026-11-13.
-- No Production rows. Keep anomaly shapes; never repair their references.
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
 SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),role text DEFAULT 'user',
 email text NOT NULL,first_name text NOT NULL,birth_date date NOT NULL,current_streak integer DEFAULT 0);
CREATE TABLE public.chapters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,
 order_index integer NOT NULL,aliases text[] DEFAULT '{}',emoji text NOT NULL DEFAULT '📚');
CREATE TABLE public.competences(id text PRIMARY KEY,chapter_id uuid REFERENCES public.chapters(id) ON DELETE CASCADE,
 name text NOT NULL,max_points integer DEFAULT 10);
CREATE TABLE public.exercises(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),title text NOT NULL,chapter text NOT NULL,
 difficulty text,competences text[],content jsonb NOT NULL,app_title text,"Is_Flash" boolean,"Need_Calculator" boolean);
CREATE TABLE public.flashcards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),chapter text NOT NULL,
 question text NOT NULL,answer text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE public.exercise_attempts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id uuid NOT NULL REFERENCES auth.users(id),exercise_id bigint REFERENCES public.exercises(id) ON DELETE SET NULL,
 score integer DEFAULT 0,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),is_correct boolean NOT NULL DEFAULT false,
 time_spent integer,attempted_at timestamptz DEFAULT now(),is_guest boolean NOT NULL DEFAULT false,is_abandoned boolean NOT NULL DEFAULT false);
CREATE TABLE public.duels(id bigserial PRIMARY KEY,player1_id uuid NOT NULL REFERENCES auth.users(id),
 player2_id uuid REFERENCES auth.users(id),status text DEFAULT 'waiting',winner_id uuid REFERENCES auth.users(id),
 created_at timestamptz DEFAULT now(),finished_at timestamptz,exercise_id bigint REFERENCES public.exercises(id),
 player1_score integer DEFAULT 0,player2_score integer DEFAULT 0,player1_time integer,player2_time integer,
 started_at timestamptz,exercise_data jsonb);
CREATE TABLE public.duel_attempts(id bigserial PRIMARY KEY,duel_id bigint NOT NULL REFERENCES public.duels(id),
 player_id uuid NOT NULL REFERENCES auth.users(id),element_id bigint NOT NULL,answer text,is_correct boolean NOT NULL,
 time_spent integer,submitted_at timestamptz DEFAULT now());
CREATE TABLE public.user_competence_scores(user_id uuid REFERENCES auth.users(id),competence_id text,
 points integer DEFAULT 0,streak integer DEFAULT 0,updated_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,competence_id));
CREATE TABLE public.ds(id uuid PRIMARY KEY,user_id uuid REFERENCES auth.users(id),deadline timestamptz,
 competence_ids text[],current_streak integer DEFAULT 0);
CREATE TABLE public.ds_competence_scores(ds_id uuid REFERENCES public.ds(id) ON DELETE CASCADE,
 competence_id text REFERENCES public.competences(id) ON DELETE CASCADE,points integer,max_points integer,updated_at timestamptz);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['chapters','competences','exercises','flashcards'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY historical_public_read ON public.%I FOR SELECT USING(true)',t);
  EXECUTE format('GRANT SELECT ON public.%I TO anon,authenticated,service_role',t);
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA public,auth TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
